const API=(window.APP_CONFIG?.API_BASE_URL||'').replace(/\/$/,'');
let token=sessionStorage.getItem('pilot_token')||'',me=null,staff=[],properties=[],channels=[],bookings=[],charts={},staffMonth='',propertyFilter='',kpiMonth='',calendarProperty='ALL',calendarStart='',calendarDays=21,calendarRange='1m',calendarRows=[],calendarQuery='',calendarSyncMessage='';
const fmtVND=v=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(Number(v||0));
const STATUS_VI={confirmed:'Đã xác nhận',completed:'Hoàn thành',pending:'Chờ xử lý',cancelled:'Đã hủy'},SEGMENT_VI={Leisure:'Nghỉ dưỡng',Business:'Công tác',Group:'Đoàn'},ROLE_VI={staff:'Nhân viên',manager:'Quản lý',admin:'Quản trị'},SEVERITY_VI={error:'Lỗi',ERROR:'Lỗi',warning:'Cảnh báo',WARNING:'Cảnh báo',info:'Thông tin',INFO:'Thông tin'};
const stVI=s=>STATUS_VI[s]||s,segVI=s=>SEGMENT_VI[s]||s,roleVI=r=>ROLE_VI[r]||r,sevVI=v=>SEVERITY_VI[v]||v;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const isoToday=()=>{const d=new Date(),p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}`};
const parseISODate=v=>{const [y,m,d]=String(v).split('-').map(Number);return new Date(y,m-1,d)};
const toISODate=d=>{const p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}`};
const addDaysISO=(v,n)=>{const d=parseISODate(v);d.setDate(d.getDate()+Number(n||0));return toISODate(d)};
const diffDays=(a,b)=>Math.round((parseISODate(b)-parseISODate(a))/86400000);
const firstOfMonthISO=v=>{const d=parseISODate(v);d.setDate(1);return toISODate(d)};
const addMonthsISO=(v,n)=>{const d=parseISODate(v),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+Number(n||0));const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,last));return toISODate(d)};
const addYearsISO=(v,n)=>addMonthsISO(v,Number(n||0)*12);
function closeModal(id){document.getElementById(id).style.display='none'}
function msg(id,t,c=''){const e=document.getElementById(id);if(e)e.innerHTML=`<div class="notice ${c}">${t}</div>`}
async function api(path,opts={}){const headers={...(opts.headers||{})};if(token)headers.Authorization=`Bearer ${token}`;if(opts.body&&!(opts.body instanceof FormData)){headers['Content-Type']='application/json';opts.body=JSON.stringify(opts.body)}const r=await fetch(API+path,{...opts,headers});if(r.status===401){let m='Không có quyền truy cập';try{m=(await r.clone().json()).detail||m}catch{}if(path!='/api/auth/login'){logout();throw new Error('Phiên đăng nhập đã hết hạn')}throw new Error(m)}if(!r.ok){let m=`HTTP ${r.status}`;try{m=(await r.json()).detail||m}catch{}throw new Error(m)}const ct=r.headers.get('content-type')||'';return ct.includes('application/json')?r.json():r}
function destroyChart(k){if(charts[k]){charts[k].destroy();delete charts[k]}}
function mkChart(id,key,type,labels,data,label='',opts={}){destroyChart(key);const el=document.getElementById(id);if(!el)return;charts[key]=new Chart(el,{type,data:{labels,datasets:[{label,data}]},options:{responsive:true,maintainAspectRatio:false,...opts}})}
function mkMultiChart(id,key,type,labels,datasets,opts={}){destroyChart(key);const el=document.getElementById(id);if(!el)return;charts[key]=new Chart(el,{type,data:{labels,datasets},options:{responsive:true,maintainAspectRatio:false,...opts}})}
async function download(path,filename){const headers={};if(token)headers.Authorization=`Bearer ${token}`;const r=await fetch(API+path,{headers});if(r.status===401){logout();throw new Error('Phiên đăng nhập đã hết hạn')}if(!r.ok){let m=`HTTP ${r.status}`;try{m=(await r.clone().json()).detail||m}catch{}throw new Error(m)}const blob=await r.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function score(v){return v==null?'N/A':Number(v).toFixed(1)+'%'}
function kpiStatus(v){if(v==null)return 'N/A';return v>=90?'Xuất sắc':v>=80?'Tốt':v>=70?'Khá':'Cần cải thiện'}
async function login(){try{const j=await api('/api/auth/login',{method:'POST',body:{username:document.getElementById('login-user').value.trim(),password:document.getElementById('login-pass').value}});token=j.access_token;sessionStorage.setItem('pilot_token',token);await boot()}catch(e){msg('login-msg',esc(e.message),'error')}}
function logout(){setReportMonth('');reportStaffId='';sessionStorage.removeItem('pilot_token');token='';me=null;document.getElementById('app-view').classList.add('hidden');document.getElementById('login-view').classList.remove('hidden')}
async function boot(){if(!token)return;try{me=await api('/api/auth/me');document.getElementById('login-view').classList.add('hidden');document.getElementById('app-view').classList.remove('hidden');document.getElementById('whoami').textContent=`Đăng nhập: ${me.username} — ${me.full_name} (${roleVI(me.role)})`;buildNav();await loadMasters();showView('dashboard')}catch(e){logout()}}
function buildNav(){let d=[['dashboard','📈 Tổng quan'],['staff','👥 Nhân viên'],['kpi','🏆 Bảng KPI']];if(['manager','admin'].includes(me.role))d.push(['datamodel','🧩 Mô hình dữ liệu']);d.push(['channels','🌐 Kênh bán'],['segments','👨‍👩‍👧‍👦 Phân khúc'],['financial','💰 Tài chính'],['stays','🏨 Thời gian lưu trú'],['calendar','🗓️ Lịch đặt phòng'],['bookings','📅 Quản lý đặt phòng'],['properties','🏢 Cơ sở lưu trú']);if(me.role==='admin')d.push(['import','📥 Nhập dữ liệu']);if(['manager','admin'].includes(me.role))d.push(['export','📤 Xuất dữ liệu'],['auditlog','📋 Nhật ký'],['validation','✅ Kiểm tra dữ liệu']);if(me.role==='admin')d.push(['auditpanel','🔍 Phân tích nhật ký'],['users','🔐 Tài khoản']);document.getElementById('nav').innerHTML=d.map(([i,l])=>`<button id="nav-${i}" onclick="showView('${i}')">${l}</button>`).join('')}
async function loadMasters(){[staff,properties,channels]=await Promise.all([api('/api/staff'),api('/api/properties'),api('/api/channels')])}
function showView(id){document.querySelectorAll('.view').forEach(x=>x.classList.add('hidden'));document.getElementById(id).classList.remove('hidden');document.querySelectorAll('nav button').forEach(x=>x.classList.remove('active'));document.getElementById(`nav-${id}`)?.classList.add('active');const f={dashboard:loadDashboard,staff:loadStaff,kpi:loadKPI,datamodel:loadDataModel,channels:loadChannels,segments:loadSegments,financial:loadFinancial,stays:loadStays,calendar:loadBookingCalendar,bookings:loadBookings,properties:loadProperties,import:loadImport,export:loadExport,auditlog:loadAudit,auditpanel:loadAuditPanel,validation:loadValidation,users:loadUsers}[id];if(f)f()}

async function loadDashboard(){const [d,ch,segs]=await Promise.all([api('/api/dashboard'),api('/api/analytics/channels'),api('/api/analytics/segments')]);document.getElementById('dashboard').innerHTML=`<h2>📈 Tổng quan</h2><div class="cards">${[['Tổng đặt phòng',d.bookings],['Đã xác nhận',d.confirmed],['Hoàn thành',d.completed],['Chờ xử lý',d.pending],['Đã hủy',d.cancelled],['Doanh thu hợp lệ',fmtVND(d.eligible_revenue)]].map(x=>`<div class="card"><div class="label">${x[0]}</div><div class="value">${x[1]}</div></div>`).join('')}</div><h3>Phân tích hiệu quả</h3><div class="grid2"><div class="chart"><h3>📊 Trạng thái đặt phòng</h3><canvas id="dash-status"></canvas></div><div class="chart"><h3>💰 Doanh thu theo kênh</h3><canvas id="dash-revenue"></canvas></div></div><div class="grid2"><div class="chart"><h3>👥 Phân khúc khách hàng</h3><canvas id="dash-segment"></canvas></div><div class="chart"><h3>🌐 Số đặt phòng theo kênh</h3><canvas id="dash-channel"></canvas></div></div><div class="notice">Phạm vi: tất cả các tháng, mọi trạng thái; ${me.role==='staff'?'đặt phòng của bạn':'đặt phòng của tất cả nhân viên'}. Bộ lọc tháng của báo cáo Nhân viên/KPI không áp dụng cho Tổng quan.</div>`;mkChart('dash-status','dashStatus','doughnut',['Đã xác nhận','Hoàn thành','Chờ xử lý','Đã hủy'],[d.confirmed,d.completed,d.pending,d.cancelled]);mkChart('dash-revenue','dashRevenue','bar',ch.map(x=>x.channel),ch.map(x=>x.revenue/1e6),'Doanh thu (triệu)',{indexAxis:'y'});mkChart('dash-segment','dashSegment','pie',segs.map(x=>segVI(x.segment)),segs.map(x=>x.bookings));mkChart('dash-channel','dashChannel','bar',ch.map(x=>x.channel),ch.map(x=>x.bookings),'Số đặt phòng')}

let staffLoadRevision=0,staffRankMetric='revenue_score',staffKpiSnapshot=null;
const staffMetrics={revenue_score:'KPI doanh thu',composite_kpi:'KPI tổng hợp'};
function missingKpiEvidence(r){return [['revenue_score','Chỉ tiêu doanh thu'],['room_nights_score','Chỉ tiêu đêm phòng'],['conversion_score','Chuyển đổi / CRM'],['payment_score','Thanh toán'],['sla_score','SLA / CRM']].filter(([key])=>r[key]==null).map(([,label])=>label).join(', ')}
function renderStaffRank(){
 const k=staffKpiSnapshot;if(!k)return;
 const key=staffRankMetric,label=staffMetrics[key],valid=k.rows.filter(r=>Number.isFinite(r[key])).sort((a,b)=>b[key]-a[key]||b.revenue-a.revenue||a.staff_id.localeCompare(b.staff_id)).slice(0,10);
 document.getElementById('staff-rank-note').textContent=`${label}: hiển thị ${valid.length} nhân viên; ${k.rows.filter(r=>!Number.isFinite(r[key])).length} nhân viên chưa có điểm này (N/A). Điểm 0 vẫn hợp lệ; thanh 0% sẽ không hiển thị.`;
 mkChart('staff-kpi-chart','staffKpi','bar',valid.map(r=>`${r.staff_id} ${r.staff_name}`),valid.map(r=>r[key]),label,{indexAxis:'y',scales:{x:{beginAtZero:true,max:100},y:{ticks:{autoSkip:false}}}});
}
async function loadStaff(){
 const revision=++staffLoadRevision,month=staffMonth,query=month?`?month=${encodeURIComponent(month)}`:'';
 try{
  const [k,allStaffRows,rawBookings]=await Promise.all([api('/api/kpi'+query),api('/api/staff'),api('/api/bookings'+query)]);
  if(revision!==staffLoadRevision)return;
  if(k.month!==(month||'ALL'))throw new Error('Kỳ dữ liệu KPI trả về không khớp với tháng đã chọn. Vui lòng tải lại.');
  const staffRows=allStaffRows.filter(s=>!reportStaffId||s.staff_id===reportStaffId);
  k.rows=k.rows.filter(s=>!reportStaffId||s.staff_id===reportStaffId);
  const periodBookings=reportRows(rawBookings);
  const km=new Map(k.rows.map(r=>[r.staff_id,r])),propsByStaff={},counts={};
  for(const b of periodBookings){counts[b.staff_id]=(counts[b.staff_id]||0)+1;(propsByStaff[b.staff_id]??=new Map()).set(b.property_id,b.property_name)}
  const months=[...new Set([...(k.evidence_months||[]),...(month?[month]:[])])].sort(),period=month||'Tất cả các tháng có dữ liệu';
  staffKpiSnapshot=k;
  document.getElementById('staff').innerHTML=`<h2>👥 Quản lý nhân viên</h2>${reportControls('staff')}${reportScopeNote()}
  <div class="notice"><strong>Kỳ: ${esc(period)}</strong> — lọc theo <strong>ngày đặt (bookingDate)</strong>, không theo ngày nhận phòng. Tổng đặt phòng trong kỳ: <strong>${periodBookings.length}</strong> (mọi trạng thái). Doanh thu chỉ tính Đã xác nhận + Hoàn thành.<br>KPI doanh thu và Xếp loại doanh thu dùng cùng một điểm doanh thu. KPI tổng hợp cần đủ 5 thành phần; thiếu dữ liệu sẽ giữ N/A.</div>
  <div class="toolbar">${me.role!=='staff'?'<button class="success" onclick="openStaffModal()">➕ Thêm nhân viên</button>':''}<strong>Tổng nhân viên: ${staffRows.length}</strong><button onclick="loadStaff()">Làm mới</button></div>
  <div class="scroll"><table><thead><tr><th>Mã NV</th><th>Họ tên</th><th>Cơ sở có booking (mọi trạng thái)</th><th>Số đặt phòng</th><th>Doanh thu hợp lệ</th><th>KPI doanh thu %</th><th>Xếp loại doanh thu</th><th>KPI tổng hợp %</th><th>Xếp loại tổng hợp / Dữ liệu</th><th>Thao tác</th></tr></thead><tbody>${staffRows.map(s=>{
   const r=km.get(s.staff_id)||{},ps=[...(propsByStaff[s.staff_id]?.entries()||[])];
   return `<tr><td>${esc(s.staff_id)}</td><td>${esc(s.staff_name)}${s.active===false?' (ngừng hoạt động)':''}</td><td>${ps.map(([id,n])=>`<span class="badge" title="${esc(id)}">${esc(n)}</span>`).join(' ')||'—'}</td><td>${counts[s.staff_id]||0}</td><td>${fmtVND(r.revenue||0)}</td><td>${score(r.revenue_score)}</td><td>${kpiStatus(r.revenue_score)}</td><td>${score(r.composite_kpi)}</td><td>${r.composite_kpi==null?`N/A — thiếu: ${esc(missingKpiEvidence(r))}`:kpiStatus(r.composite_kpi)} (${r.coverage||0}/5)</td><td><button class="small" onclick="openStaffReconciliation('${esc(s.staff_id)}')">Đối chiếu</button>${me.role==='staff'?'':`<button class="warn small" onclick='openStaffModal(${JSON.stringify(s)})'>Sửa</button><button class="danger small" onclick="deleteStaff('${s.staff_id}')">Xóa</button>`}</td></tr>`;
  }).join('')}</tbody></table></div>
  <h3>Phân tích KPI nhân viên — ${esc(period)}</h3><div class="toolbar"><label>Chỉ số xếp hạng Top 10:</label><select onchange="staffRankMetric=this.value;renderStaffRank()">${Object.entries(staffMetrics).map(([key,label])=>`<option value="${key}" ${key===staffRankMetric?'selected':''}>${label}</option>`).join('')}</select></div><div id="staff-rank-note" class="notice"></div>
  <div class="grid2"><div class="chart"><h3>📊 Top 10 nhân viên</h3><canvas id="staff-kpi-chart"></canvas></div><div class="chart"><h3>📈 Xu hướng KPI tổng hợp (các tháng)</h3><canvas id="staff-trend-chart"></canvas></div></div>
  <div class="grid2"><div class="chart"><h3>💰 Top 10 doanh thu hợp lệ</h3><canvas id="staff-revenue-chart"></canvas></div><div class="chart"><h3>🎯 Top 10 số đặt phòng</h3><canvas id="staff-bookings-chart"></canvas></div></div><div id="staff-trend-note" class="muted">N/A được thể hiện là khoảng trống trên biểu đồ. Đang tải…</div>`;
  renderStaffRank();
  const revenueTop=[...k.rows].sort((a,b)=>b.revenue-a.revenue).slice(0,10),bookingTop=[...staffRows].sort((a,b)=>(counts[b.staff_id]||0)-(counts[a.staff_id]||0)).slice(0,10);
  mkChart('staff-revenue-chart','staffRevenue','doughnut',revenueTop.map(r=>r.staff_name),revenueTop.map(r=>r.revenue));
  mkChart('staff-bookings-chart','staffBookings','bar',bookingTop.map(r=>r.staff_name),bookingTop.map(r=>counts[r.staff_id]||0),'Số đặt phòng');
  if(months.length){
   const monthly=await Promise.all(months.map(m=>m===month?Promise.resolve(k):api(`/api/kpi?month=${encodeURIComponent(m)}`)));
   if(revision!==staffLoadRevision)return;
   const top=[...k.rows].sort((a,b)=>(b.composite_kpi??-1)-(a.composite_kpi??-1)||b.revenue-a.revenue).slice(0,5);
   const series=top.map(s=>({label:s.staff_name,data:monthly.map(md=>md.rows.find(r=>r.staff_id===s.staff_id)?.composite_kpi??null),fill:false,spanGaps:false,tension:.25}));
   mkMultiChart('staff-trend-chart','staffTrend','line',months,series,{plugins:{legend:{position:'bottom'}},scales:{y:{beginAtZero:true,max:100}}});
   document.getElementById('staff-trend-note').textContent='Xu hướng KPI tổng hợp: thiếu dữ liệu (N/A) hiển thị là khoảng trống, không phải điểm 0.';
  }
 }catch(e){if(revision===staffLoadRevision)msg('staff',`Không tải được dữ liệu nhân viên: ${esc(e.message)}`,'error')}
}

function openStaffModal(s=null){const id=s?.staff_id||'';document.getElementById('dynamic-modal').innerHTML=`<div class="modal-card"><div class="modal-head"><h2>${s?'Sửa':'Thêm'} nhân viên</h2><span class="x" onclick="closeModal('dynamic-modal')">&times;</span></div><div class="form-row"><div class="form-group"><label>Mã nhân viên</label><input id="s-id" value="${esc(id)}" ${s?'disabled':''}></div><div class="form-group"><label>Họ tên</label><input id="s-name" value="${esc(s?.staff_name||'')}"></div></div><div class="form-row"><div class="form-group"><label>Nhóm</label><input id="s-team" value="${esc(s?.team||'')}"></div><div class="form-group"><label>Chỉ tiêu doanh thu tháng (VND)</label><input id="s-target" type="number" value="${s?.monthly_base_revenue_target_vnd||5000000}"></div></div><div class="form-group"><label>Đang hoạt động</label><select id="s-active"><option value="true" ${s?.active!==false?'selected':''}>Có</option><option value="false" ${s?.active===false?'selected':''}>Không</option></select></div><button class="success" onclick="saveStaff('${id}')">💾 Lưu</button></div>`;document.getElementById('dynamic-modal').style.display='block'}
async function saveStaff(existing=''){const body={staff_id:existing||document.getElementById('s-id').value.trim(),staff_name:document.getElementById('s-name').value.trim(),team:document.getElementById('s-team').value.trim(),start_date:null,active:document.getElementById('s-active').value==='true',monthly_base_revenue_target_vnd:+document.getElementById('s-target').value};try{await api(existing?`/api/staff/${existing}`:'/api/staff',{method:existing?'PUT':'POST',body});closeModal('dynamic-modal');await loadMasters();loadStaff()}catch(e){alert(e.message)}}
async function deleteStaff(id){if(!confirm(`Xóa ${id}? Nếu nhân viên đã có dữ liệu liên quan, hệ thống sẽ chặn thao tác xóa; khi đó hãy đặt Đang hoạt động = Không.`))return;try{await api(`/api/staff/${id}`,{method:'DELETE'});await loadMasters();loadStaff()}catch(e){alert(e.message)}}

async function loadKPI(){document.getElementById('kpi').innerHTML=`<h2>🏆 Bảng KPI tổng hợp & Xếp hạng nhân viên</h2>${reportControls('kpi')}${reportScopeNote()}<div class="notice">KPI tổng hợp = Doanh thu 40% + Đêm phòng 20% + Chuyển đổi 15% + Thanh toán đúng hạn 15% + SLA 10%. Thiếu dữ liệu giữ N/A. Bao gồm nhân viên ngừng hoạt động để bảo toàn báo cáo lịch sử.</div><div class="toolbar"><button onclick="refreshKPI()">Làm mới</button><button onclick="exportKPI()">Xuất CSV (toàn bộ nhân viên được phép xem trong kỳ)</button></div><div id="kpi-month-status"></div><div id="kpi-body"></div>`;await refreshKPI()}
let kpiLoadRevision=0;
async function refreshKPI(){const revision=++kpiLoadRevision,m=staffMonth;try{const d=await api('/api/kpi'+(m?'?month='+encodeURIComponent(m):''));if(revision!==kpiLoadRevision||m!==staffMonth)return;renderKPI(d)}catch(e){msg('kpi-month-status',esc(e.message),'error')}}
function renderKPI(d){d={...d,rows:d.rows.filter(r=>!reportStaffId||r.staff_id===reportStaffId)};const valid=d.rows.filter(r=>r.composite_kpi!=null).sort((a,b)=>b.composite_kpi-a.composite_kpi),avg=k=>{const a=d.rows.map(r=>r[k]).filter(v=>v!=null);return a.length?a.reduce((s,v)=>s+v,0)/a.length:0};const coverage=k=>d.rows.filter(r=>r[k]!=null).length;const periodLabel=d.month==='ALL'?'Tất cả các tháng':d.month;document.getElementById('kpi-month-status').innerHTML=`<strong>Kỳ đã chọn:</strong> ${periodLabel}. <strong>Các tháng có dữ liệu:</strong> ${(d.evidence_months||[]).join(', ')||'Không có'}.`;document.getElementById('kpi-body').innerHTML=`<div class="cards"><div class="card"><div class="label">Tổng nhân viên</div><div class="value">${d.rows.length}</div></div><div class="card"><div class="label">Nhân viên đủ điểm</div><div class="value">${valid.length}</div></div><div class="card"><div class="label">Độ phủ dữ liệu trung bình</div><div class="value">${d.rows.length?(d.rows.reduce((s,r)=>s+r.coverage,0)/d.rows.length/5*100).toFixed(0):0}%</div></div></div><div class="grid2"><div class="chart"><h3>🏅 Top 10 nhân viên theo KPI tổng hợp — ${periodLabel}</h3><canvas id="kpi-rank"></canvas></div><div class="chart"><h3>📊 Điểm trung bình các thành phần KPI — ${periodLabel}</h3><div class="muted">Độ phủ: Doanh thu ${coverage('revenue_score')}; Đêm phòng ${coverage('room_nights_score')}; Chuyển đổi ${coverage('conversion_score')}; Thanh toán ${coverage('payment_score')}; SLA ${coverage('sla_score')}</div><canvas id="kpi-components"></canvas></div></div><h3>Xếp hạng nhân viên — ${periodLabel}</h3><div class="scroll"><table><thead><tr><th>Hạng</th><th>Mã NV</th><th>Họ tên</th><th>Booking</th><th>Cơ sở có booking</th><th>Doanh thu (VND)</th><th>KPI doanh thu</th><th>KPI đêm phòng</th><th>Chuyển đổi</th><th>Thanh toán đúng hạn</th><th>SLA</th><th>KPI tổng hợp</th><th>Xếp loại</th><th>Độ phủ</th></tr></thead><tbody>${[...d.rows].sort((a,b)=>(b.composite_kpi??-1)-(a.composite_kpi??-1)).map((r,i)=>`<tr><td>${r.composite_kpi==null?'—':i+1}</td><td>${r.staff_id}</td><td>${esc(r.staff_name)}${r.active===false?' (ngừng hoạt động)':''}</td><td>${r.bookings??'—'}</td><td>${esc((r.property_ids||[]).join(', '))}</td><td>${fmtVND(r.revenue)}</td><td>${score(r.revenue_score)}</td><td>${score(r.room_nights_score)}</td><td>${score(r.conversion_score)}</td><td>${score(r.payment_score)}</td><td>${score(r.sla_score)}</td><td>${r.composite_kpi==null?'N/A':r.composite_kpi.toFixed(1)}</td><td>${kpiStatus(r.composite_kpi)}</td><td>${r.coverage}/5</td></tr>`).join('')}</tbody></table></div>`;mkChart('kpi-rank','kpiRank','bar',valid.slice(0,10).map(r=>`${r.staff_id} ${r.staff_name}`),valid.slice(0,10).map(r=>r.composite_kpi),'KPI tổng hợp',{indexAxis:'y',scales:{x:{beginAtZero:true,max:100}}});mkChart('kpi-components','kpiComp','bar',['Doanh thu','Đêm phòng','Chuyển đổi','Thanh toán đúng hạn','SLA'],['revenue_score','room_nights_score','conversion_score','payment_score','sla_score'].map(avg),'Điểm %',{scales:{y:{beginAtZero:true,max:100}}})}
function exportKPI(){const m=staffMonth;download(`/api/kpi/export-csv${m?`?month=${m}`:''}`,`kpi_ranking_${m||'ALL'}_v1.0.2.csv`).catch(e=>alert(e.message))}

async function loadDataModel(){const d=await api('/api/data-model');document.getElementById('datamodel').innerHTML=`<h2>🧩 Mô hình dữ liệu Pilot V1.0.2f</h2><div class="notice">Các thực thể chuẩn hóa ở backend được kiểm tra theo quy tắc khóa chính/khóa ngoại (PK/FK) trong cơ sở dữ liệu tập trung. Việc đồng bộ dữ liệu gốc không bao giờ âm thầm xóa lịch sử giao dịch.</div><div class="cards"><div class="card"><div class="label">Lỗi</div><div class="value">${d.error_count}</div></div><div class="card"><div class="label">Cảnh báo</div><div class="value">${d.warning_count}</div></div></div><div class="toolbar"><button class="success" onclick="refreshDataModel()">🔄 Dựng lại / Làm mới mô hình dữ liệu</button><button class="purple" onclick="syncMasterDeps()">🔗 Đồng bộ phụ thuộc dữ liệu gốc</button><button onclick="checkDataModel()">✅ Kiểm tra khóa & quan hệ</button><button onclick="exportDataModelJson()">📥 Xuất mô hình dữ liệu JSON</button><button onclick="exportIntegrityCsv()">📥 Xuất báo cáo toàn vẹn CSV</button></div><div id="dm-msg"></div><div class="grid2"><div><h3>Tổng quan thực thể</h3><div class="scroll"><table><thead><tr><th>Thực thể</th><th>Khóa chính</th><th>Số dòng</th><th>Trạng thái</th></tr></thead><tbody>${d.entities.map(x=>`<tr><td>${x.entity}</td><td>${x.primary_key}</td><td>${x.rows}</td><td>${d.issues.some(i=>i.entity===x.entity)?'⚠️ Cần xem lại':'✅ Đạt'}</td></tr>`).join('')}</tbody></table></div></div><div><h3>Quy tắc quan hệ</h3><div class="notice">Bookings.staff_id → Staff.staff_id<br>Staff ↔ Properties thông qua Bookings<br>Bookings.property_id → Properties.property_id<br>Bookings.room_type_id → Room Types(property_id + room_type_id)<br>KPI Targets.staff_id → Staff.staff_id<br>Users.staff_id → Staff.staff_id (không bắt buộc với Quản lý/Quản trị)</div></div></div><h3>Bảng thực thể</h3><div id="dm-entities"></div><h3>Vấn đề toàn vẹn dữ liệu</h3><div class="scroll"><table><thead><tr><th>Mức độ</th><th>Thực thể</th><th>Mã bản ghi</th><th>Quy tắc</th><th>Vấn đề</th></tr></thead><tbody>${d.issues.length?d.issues.map(i=>`<tr><td>${sevVI(i.severity)}</td><td>${i.entity}</td><td>${i.record_id}</td><td>${i.rule}</td><td>${esc(i.issue)}</td></tr>`).join(''):'<tr><td colspan="5">✅ Không có vấn đề toàn vẹn dữ liệu.</td></tr>'}</tbody></table></div>`;await renderDataModelEntities()}
async function renderDataModelEntities(){const [u,s,p,c]=await Promise.all([me.role==='admin'?api('/api/users'):Promise.resolve([]),api('/api/staff'),api('/api/properties'),api('/api/channels')]);const el=document.getElementById('dm-entities');if(!el)return;el.innerHTML=`${me.role==='admin'?`<div class="chart"><h3>Tài khoản</h3><div class="scroll"><table><thead><tr><th>Tên đăng nhập</th><th>Họ tên</th><th>Vai trò</th><th>Mã NV</th><th>Hoạt động</th></tr></thead><tbody>${u.map(x=>`<tr><td>${x.username}</td><td>${esc(x.full_name)}</td><td>${roleVI(x.role)}</td><td>${x.staff_id||'—'}</td><td>${x.active?'Có':'Không'}</td></tr>`).join('')}</tbody></table></div></div>`:''}<div class="grid2"><div class="chart"><h3>Nhân viên</h3><div class="scroll"><table><thead><tr><th>Mã NV</th><th>Họ tên</th><th>Nhóm</th><th>Chỉ tiêu</th></tr></thead><tbody>${s.map(x=>`<tr><td>${x.staff_id}</td><td>${esc(x.staff_name)}</td><td>${esc(x.team)}</td><td>${fmtVND(x.monthly_base_revenue_target_vnd)}</td></tr>`).join('')}</tbody></table></div></div><div class="chart"><h3>Cơ sở lưu trú</h3><div class="scroll"><table><thead><tr><th>Mã</th><th>Tên</th><th>Trạng thái</th><th>Tổng số phòng</th></tr></thead><tbody>${p.map(x=>`<tr><td>${x.property_id}</td><td>${esc(x.property_name)}</td><td>${x.active?'Đang hoạt động':'Ngừng hoạt động'}</td><td>${x.total_rooms}</td></tr>`).join('')}</tbody></table></div></div></div><div class="chart"><h3>Loại phòng & Quỹ phòng</h3><div class="scroll"><table><thead><tr><th>Cơ sở</th><th>Loại phòng</th><th>Tên</th><th>Số lượng</th></tr></thead><tbody>${p.flatMap(x=>x.room_types.map(r=>`<tr><td>${x.property_id}</td><td>${r.room_type_id}</td><td>${esc(r.room_type_name)}</td><td>${r.quantity}</td></tr>`)).join('')}</tbody></table></div></div><div class="chart"><h3>Kênh bán</h3><div class="scroll"><table><thead><tr><th>Mã kênh</th><th>Tên</th><th>Hoa hồng</th><th>SLA</th></tr></thead><tbody>${c.map(x=>`<tr><td>${x.channel_id}</td><td>${esc(x.channel_name)}</td><td>${(x.commission_rate*100).toFixed(0)}%</td><td>${x.response_sla_minutes} phút</td></tr>`).join('')}</tbody></table></div></div>`}
