const calendarColors=['#147d72','#315bb3','#9b4d96','#ae5b26','#697c1d','#b13d59','#287a9c','#7253b5','#795548','#28785a'];
function calendarPropertyColor(id){const ordered=[...properties].sort((a,b)=>a.property_id.localeCompare(b.property_id));return calendarColors[Math.max(0,ordered.findIndex(p=>p.property_id===id))%calendarColors.length]}
function calendarMonthSections(start,end){
  if(calendarRange==='1m'||calendarRange==='2m'||calendarRange==='3m'||calendarRange==='1y-around'){
    const out=[];let cursor=start;
    while(cursor<end){let next=firstOfMonthISO(addMonthsISO(firstOfMonthISO(cursor),1));if(next>end)next=end;out.push([cursor,next]);cursor=next}
    return out;
  }
  return [[start,end]];
}
function renderBookingCalendar(){
  const selected=calendarProperty==='ALL'?properties:properties.filter(p=>p.property_id===calendarProperty),r=calendarRangeMeta(),start=r.start,end=r.end;
  if(!selected.length){document.getElementById('calendar').innerHTML='<div class="notice warning">Cơ sở lưu trú không tồn tại.</div>';return}
  const q=calendarQuery,rows=q?calendarRows.filter(b=>[b.booking_id,b.staff_id,b.staff_name,b.property_id,b.property_name,b.room_type_id,b.room_type_name,b.status,stVI(b.status)].some(v=>String(v||'').toLowerCase().includes(q))):calendarRows;
  const monthlyRates=calendarMonthlyOccupancy(selected,calendarRows,start,end);
  const rateCards=monthlyRates.map(m=>`<div class="calendar-month-rate"><span>Tháng ${m.month.slice(5)}/${m.month.slice(0,4)}</span><strong>${m.percent==null?'Chưa có số phòng':m.percent.toLocaleString('vi-VN',{minimumFractionDigits:1,maximumFractionDigits:1})+'%'}</strong><small>${m.roomNights.toLocaleString('vi-VN')} / ${m.available.toLocaleString('vi-VN')} đêm phòng${m.percent>100?' — Vượt công suất':''}</small></div>`).join('');
  const propOpts=`<option value="ALL" ${calendarProperty==='ALL'?'selected':''}>Tất cả cơ sở</option>`+properties.map(x=>`<option value="${esc(x.property_id)}" ${x.property_id===calendarProperty?'selected':''}>${esc(x.property_id)} — ${esc(x.property_name)}</option>`).join('');
  const rangeOpts=[['7d','7 ngày'],['14d','14 ngày'],['21d','21 ngày'],['30d','30 ngày'],['1m','1 tháng (trọn tháng)'],['2m','2 tháng (trọn tháng)'],['3m','3 tháng (trọn tháng)'],['1y-around','1 năm trước + 1 năm sau Hôm nay']].map(([v,l])=>`<option value="${v}" ${v===calendarRange?'selected':''}>${l}</option>`).join('');
  const body=calendarMonthSections(start,end).map(([from,to])=>{
    const count=diffDays(from,to),dayWidth=calendarFitDayWidth(count),days=Array.from({length:count},(_,i)=>addDaysISO(from,i));
    const monthLabel=new Intl.DateTimeFormat('vi-VN',{month:'long',year:'numeric'}).format(parseISODate(from));
    const groups=selected.map(p=>{
      const color=calendarPropertyColor(p.property_id);
      const roomTypes=(p.room_types||[]).filter(rt=>rt.active);
      const content=roomTypes.map(rt=>{
        const br=rows.filter(b=>b.property_id===p.property_id&&b.room_type_id===rt.room_type_id&&b.check_in_date<to&&b.check_out_date>from),slots=allocateCalendarSlots(rt,br);
        const slotHtml=slots.map(slot=>{
          const clicks=days.map(day=>`<button class="cal-day-click" ${slot.overflow?'disabled':''} title="Thêm đặt phòng: ${day}" onclick="openCalendarAdd('${p.property_id}','${rt.room_type_id}','${day}',${slot.number})"></button>`).join('');
          const bars=slot.items.map(it=>{const b=it.booking,visStart=b.check_in_date<from?from:b.check_in_date,visEnd=b.check_out_date>to?to:b.check_out_date,left=diffDays(from,visStart)*dayWidth+2,width=Math.max(8,diffDays(visStart,visEnd)*dayWidth-4),multi=it.copies>1?` ${it.copy+1}/${it.copies}`:'';const title=`${p.property_name} | ${b.booking_id} | NV ${b.staff_id} | ${calendarStatusLabel(b.status)} | ${b.check_in_date} → ${b.check_out_date} | ${b.nights} đêm | ${b.number_of_rooms} phòng${b.can_edit?' | Nhấn để sửa':' | Chỉ xem'}`;return `<button class="cal-booking status-${b.status}${dayWidth<40?' narrow':''}" style="left:${left}px;width:${width}px;--property-color:${color}" title="${esc(title)}" onclick="event.stopPropagation();openCalendarBooking('${b.booking_id}')"><strong>${esc(b.booking_id)}</strong> · ${esc(b.staff_id)} · ${b.nights}đ${multi}</button>`}).join('');
          return `<div class="cal-slot-row ${slot.overflow?'overbook':''}"><div class="cal-slot-meta"><strong>${esc(rt.room_type_id)}</strong><span>${esc(rt.room_type_name)}</span><small>${slot.label}${slot.overflow?' • VƯỢT SỐ PHÒNG':''}</small></div><div class="cal-timeline" style="width:${count*dayWidth}px;--day-width:${dayWidth}px"><div class="cal-click-grid" style="grid-template-columns:repeat(${count},${dayWidth}px)">${clicks}</div>${bars}</div></div>`;
        }).join('');
        return `<div class="cal-roomtype-head"><strong>${esc(rt.room_type_id)} — ${esc(rt.room_type_name)}</strong><span>${rt.quantity} phòng • tối đa ${rt.max_guests_per_room} khách/phòng</span></div>${slotHtml}`;
      }).join('')||'<div class="notice warning">Cơ sở chưa có loại phòng đang hoạt động.</div>';
      return `<div class="cal-property-head" style="--property-color:${color}"><strong>${esc(p.property_id)} — ${esc(p.property_name)}</strong><span>${p.total_rooms} phòng</span></div>${content}`;
    }).join('');
    return `<section class="cal-month"><h3>${esc(monthLabel)} <small>${from} → ${addDaysISO(to,-1)}</small></h3><div class="calendar-scroll"><div class="cal-inner" style="min-width:${CAL_LEFT+count*dayWidth}px"><div class="cal-header"><div class="cal-left-head">Cơ sở / Loại phòng / Slot</div><div class="cal-dates" style="grid-template-columns:repeat(${count},${dayWidth}px)">${days.map((d,i)=>calendarDateHead(d,dayWidth,i)).join('')}</div></div>${groups}</div></div></section>`;
  }).join('');
  const first=selected[0],addProperty=calendarProperty==='ALL'?first.property_id:calendarProperty;
  const propertyLegend=selected.map(p=>`<span><i class="lg" style="background:${calendarPropertyColor(p.property_id)}"></i>${esc(p.property_id)} — ${esc(p.property_name)}</span>`).join('');
  const calHost=document.getElementById('calendar');calendarLastWidth=calHost.clientWidth;calHost.innerHTML=`<div class="split-title"><div><h2>🗓️ Lịch đặt phòng — ${calendarProperty==='ALL'?'Tất cả cơ sở':esc(first.property_name)}</h2><div class="muted">${start} → ${addDaysISO(end,-1)} • ${r.days} ngày • ${esc(r.label)}</div></div><button class="success" onclick="openCalendarAdd('${addProperty}','', '${isoToday()}')">➕ Thêm đặt phòng</button></div>
  <div class="calendar-controls"><select onchange="calendarSetProperty(this.value)">${propOpts}</select><select onchange="calendarSetRange(this.value)">${rangeOpts}</select><button class="secondary" onclick="calendarShift(-1)" title="Kỳ trước">‹</button><button onclick="calendarToday()">Hôm nay</button><button class="secondary" onclick="calendarShift(1)" title="Kỳ sau">›</button><button id="calendar-sync-btn" class="purple" onclick="synchronizeBookingCalendar()">🔄 Đồng bộ</button><input value="${esc(calendarQuery)}" oninput="calendarSetQuery(this.value)" placeholder="Tìm mã đặt phòng, mã NV, cơ sở, trạng thái..."></div>
  <div class="notice">Lịch dùng <strong>ngày lưu trú</strong>, hiển thị booking của <strong>tất cả nhân viên</strong> tại cơ sở đã chọn (không tính đã hủy). Báo cáo Nhân viên/KPI dùng <strong>ngày đặt</strong>. Một mã booking có thể có nhiều thanh nếu nhiều phòng hoặc qua nhiều tháng. Muốn đối chiếu riêng S001: mở Nhân viên → Đối chiếu.</div>${calendarSyncMessage?`<div class="notice ${calendarSyncMessage.startsWith('✅')?'successbox':'error'} calendar-sync-message">${calendarSyncMessage}</div>`:''}
  <section class="calendar-monthly-summary"><h3>Tỷ lệ % đặt phòng</h3><div class="calendar-monthly-rates">${rateCards}</div><p class="muted">Tính cho cả tháng: đêm phòng đã xác nhận/hoàn tất ÷ tổng đêm phòng khả dụng. Không tính ngày trả phòng, chờ xử lý hoặc đã hủy. Theo cơ sở đang chọn; ô tìm kiếm không làm thay đổi tỷ lệ.${calendarLoadedAt?` Dữ liệu cập nhật lúc ${esc(calendarLoadedAt)}.`:''}</p></section>
  <div class="calendar-legend">${propertyLegend}<span class="muted">Màu thể hiện cơ sở lưu trú; đặt phòng Chờ xử lý có sọc; Đã hủy không chiếm slot. Nhấn vào đặt phòng để xem/sửa theo quyền.</span></div>
  ${body}
  <div class="notice"><strong>Lưu ý:</strong> Slot được lưu cố định theo cơ sở và loại phòng; chưa phải số phòng vật lý. Đặt phòng đã hủy không chiếm slot và được xem trong tab Đặt phòng. Nút Đồng bộ nạp lại dữ liệu mới nhất từ bảng Đặt phòng. Nhân viên chỉ sửa được đặt phòng của mình.</div>`;
}
function openCalendarAdd(propertyId,roomTypeId,dateStr,slot=null){openBooking({property_id:propertyId,room_type_id:roomTypeId,check_in_date:dateStr,check_out_date:addDaysISO(dateStr,1),calendar_slots:slot?[slot]:[]})}
async function openCalendarBooking(id){
  const c=calendarRows.find(x=>x.booking_id===id);if(!c)return;
  if(!c.can_edit){alert(`${id}\nNhân viên: ${c.staff_id}\nLoại phòng: ${c.room_type_id}\nLưu trú: ${c.check_in_date} → ${c.check_out_date}\nTrạng thái: ${stVI(c.status)}\n\nBạn chỉ có quyền xem đặt phòng của nhân viên khác.`);return}
  try{const own=await api('/api/bookings');const b=own.find(x=>x.booking_id===id);if(!b)throw new Error('Tài khoản này không xem được chi tiết đặt phòng.');editBooking(b)}catch(e){alert(e.message)}
}

async function loadBookings(){bookings=await api('/api/bookings');const status=document.getElementById('bookings-status-cache')?.value||'';renderBookings(status)}
function renderBookings(status=''){const base=reportRows(bookings),rows=status?base.filter(b=>b.status===status):base;document.getElementById('bookings').innerHTML=`<h2>📅 Quản lý đặt phòng</h2>${reportControls('bookings')}${reportScopeNote()}<div class="toolbar"><button class="success" onclick="openBooking()">➕ Thêm đặt phòng</button><label>Lọc trạng thái:</label><select id="bookings-status-cache" onchange="renderBookings(this.value)"><option value="">Tất cả</option>${['confirmed','completed','pending','cancelled'].map(s=>`<option value="${s}" ${s===status?'selected':''}>${stVI(s)}</option>`).join('')}</select><strong>Tổng: ${rows.length}</strong></div><div class="scroll"><table><thead><tr><th>Mã</th><th>Nhân viên</th><th>Cơ sở</th><th>Loại phòng</th><th>Kênh</th><th>Ngày đặt</th><th>Nhận phòng</th><th>Trả phòng</th><th>Số khách</th><th>Trạng thái</th><th>Doanh thu</th><th>Thao tác</th></tr></thead><tbody>${rows.map(b=>`<tr><td>${b.booking_id}</td><td>${esc(b.staff_id)} — ${esc(b.staff_name)}</td><td>${esc(b.property_name)}</td><td>${b.room_type_id} - ${esc(b.room_type_name)}</td><td>${esc(b.channel)}</td><td>${b.booking_date}</td><td>${b.check_in_date}</td><td>${b.check_out_date}</td><td>${b.number_of_guests}</td><td class="status-${b.status}">${stVI(b.status)}</td><td>${fmtVND(b.revenue)}</td><td><button class="warn small" onclick='editBooking(${JSON.stringify(b)})'>Sửa</button><button class="danger small" onclick="deleteBooking('${b.booking_id}')">Xóa</button></td></tr>`).join('')}</tbody></table></div>`}
function openBooking(pref={}){fillBookingSelects();document.getElementById('booking-modal-title').textContent='Thêm đặt phòng';document.getElementById('b-id').value='';document.querySelectorAll('#booking-modal input').forEach(x=>{if(x.type!=='hidden')x.value='' });document.getElementById('b-guests').value=2;document.getElementById('b-rooms').value=1;document.getElementById('b-revenue').value=0;document.getElementById('b-deposit').value=0;document.getElementById('b-date').value=isoToday();document.getElementById('b-in').value=pref.check_in_date||isoToday();document.getElementById('b-out').value=pref.check_out_date||addDaysISO(document.getElementById('b-in').value,1);document.getElementById('b-status').value=pref.status||'confirmed';document.getElementById('b-segment').value='Leisure';if(pref.property_id){document.getElementById('b-property').value=pref.property_id;fillRoomTypes(pref.room_type_id||'')}if(pref.room_type_id)document.getElementById('b-room').value=pref.room_type_id;if(me.role!=='staff'&&pref.staff_id)document.getElementById('b-staff').value=pref.staff_id;document.getElementById('b-slots').value=(pref.calendar_slots||[]).join(', ');document.getElementById('booking-modal').style.display='block'}
function fillBookingSelects(){document.getElementById('b-staff-wrap').classList.toggle('hidden',me.role==='staff');document.getElementById('b-staff').innerHTML=staff.map(s=>`<option value="${s.staff_id}">${s.staff_id} - ${esc(s.staff_name)}</option>`).join('');document.getElementById('b-property').innerHTML='<option value="">-- Chọn cơ sở --</option>'+properties.filter(p=>p.active).map(p=>`<option value="${p.property_id}">${p.property_id} - ${esc(p.property_name)}</option>`).join('');document.getElementById('b-channel').innerHTML=channels.filter(c=>c.active).map(c=>`<option>${esc(c.channel_name)}</option>`).join('');fillRoomTypes()}
function fillRoomTypes(pref=''){document.getElementById('b-slots').value='';const p=properties.find(x=>x.property_id===document.getElementById('b-property').value);document.getElementById('b-room').innerHTML=(p?.room_types||[]).filter(r=>r.active).map(r=>`<option value="${r.room_type_id}">${r.room_type_id} - ${esc(r.room_type_name)} (${r.quantity} phòng; tối đa ${r.max_guests_per_room} khách/phòng)</option>`).join('');if(pref)document.getElementById('b-room').value=pref}
function editBooking(b){fillBookingSelects();document.getElementById('booking-modal-title').textContent=`Sửa ${b.booking_id}`;document.getElementById('b-id').value=b.booking_id;if(me.role!=='staff')document.getElementById('b-staff').value=b.staff_id;document.getElementById('b-property').value=b.property_id;fillRoomTypes(b.room_type_id);document.getElementById('b-slots').value=(b.calendar_slots||[]).join(', ');[['b-date','booking_date'],['b-in','check_in_date'],['b-out','check_out_date'],['b-guests','number_of_guests'],['b-rooms','number_of_rooms'],['b-channel','channel'],['b-status','status'],['b-segment','segment'],['b-revenue','revenue'],['b-deposit','deposit_due'],['b-deposit-date','deposit_due_date'],['b-notes','notes']].forEach(([id,k])=>document.getElementById(id).value=b[k]??'');document.getElementById('booking-modal').style.display='block'}
async function saveBooking(){const slotText=document.getElementById('b-slots').value.trim();const chosen=slotText?slotText.split(',').map(x=>Number(x.trim())):null;if(chosen&&chosen.some(n=>!Number.isInteger(n)||n<1)){alert('Nhập số slot nguyên dương, cách nhau bằng dấu phẩy.');return}const id=document.getElementById('b-id').value,body={calendar_slots:chosen,staff_id:me.role==='staff'?null:document.getElementById('b-staff').value,property_id:document.getElementById('b-property').value,room_type_id:document.getElementById('b-room').value,booking_date:document.getElementById('b-date').value,check_in_date:document.getElementById('b-in').value,check_out_date:document.getElementById('b-out').value,number_of_guests:+document.getElementById('b-guests').value,number_of_rooms:+document.getElementById('b-rooms').value,status:document.getElementById('b-status').value,channel:document.getElementById('b-channel').value,segment:document.getElementById('b-segment').value,revenue:+document.getElementById('b-revenue').value,deposit_due:+document.getElementById('b-deposit').value,deposit_due_date:document.getElementById('b-deposit-date').value||null,notes:document.getElementById('b-notes').value};try{const health=await api('/api/health');if(!health.persistent_slots)throw new Error('Cần cập nhật backend V1.0.2l trước khi lưu slot.');await api(id?`/api/bookings/${id}`:'/api/bookings',{method:id?'PUT':'POST',body});closeModal('booking-modal');if(!document.getElementById('calendar').classList.contains('hidden'))await loadBookingCalendar();else await loadBookings()}catch(e){alert(e.message)}}
async function deleteBooking(id){if(!confirm(`Xóa ${id}? Nếu có dữ liệu thanh toán/CRM liên kết, hệ thống sẽ chặn thao tác xóa.`))return;try{await api(`/api/bookings/${id}`,{method:'DELETE'});await loadBookings()}catch(e){alert(e.message)}}

async function loadProperties(){properties=await api('/api/properties');bookings=reportRows(await api('/api/bookings'));const selected=propertyFilter;const shown=selected?properties.filter(p=>p.property_id===selected):properties;const scoped=selected?bookings.filter(b=>b.property_id===selected):bookings;const rev=scoped.filter(b=>['confirmed','completed'].includes(b.status)).reduce((s,b)=>s+b.revenue,0);document.getElementById('properties').innerHTML=`<h2>🏢 Danh mục cơ sở lưu trú & Thống kê</h2>${reportControls('properties')}${reportScopeNote()}<div class="notice">Quỹ phòng được quản lý tập trung ở backend. Nhân viên có thể bán phòng cho nhiều cơ sở thông qua các bản ghi đặt phòng.</div><div class="toolbar">${me.role!=='staff'?'<button class="success" onclick="openPropertyModal()">➕ Thêm cơ sở</button>':''}<label><strong>Chọn cơ sở:</strong></label><select onchange="propertyFilter=this.value;loadProperties()"><option value="">Tất cả cơ sở</option>${properties.map(p=>`<option value="${p.property_id}" ${p.property_id===selected?'selected':''}>${p.property_id} - ${esc(p.property_name)}</option>`).join('')}</select><strong>Cơ sở hiển thị: ${shown.length} / ${properties.length}</strong></div><div class="scroll"><table><thead><tr><th>Mã cơ sở</th><th>Tên cơ sở</th><th>Trạng thái</th><th>Loại phòng</th><th>Tổng số phòng</th><th>Số đặt phòng</th><th>Thao tác</th></tr></thead><tbody>${shown.map(p=>`<tr><td><strong>${p.property_id}</strong></td><td>${esc(p.property_name)}</td><td>${p.active?'✅ Đang hoạt động':'🔒 Ngừng hoạt động'}</td><td>${p.room_types.map(r=>`<span class="badge">${esc(r.room_type_name)} (${r.quantity})</span>`).join(' ')}</td><td>${p.total_rooms}</td><td>${bookings.filter(b=>b.property_id===p.property_id).length}</td><td>${me.role==='staff'?'—':`<button class="warn small" onclick='openPropertyModal(${JSON.stringify(p)})'>Sửa</button><button class="danger small" onclick="deleteProperty('${p.property_id}')">Xóa</button>`}</td></tr>`).join('')}</tbody></table></div><div class="cards"><div class="card"><div class="label">${selected?'Cơ sở đã chọn':'Số cơ sở'}</div><div class="value">${selected||shown.length}</div></div><div class="card"><div class="label">Số đặt phòng</div><div class="value">${scoped.length}</div></div><div class="card"><div class="label">Đã xác nhận</div><div class="value">${scoped.filter(b=>b.status==='confirmed').length}</div></div><div class="card"><div class="label">Hoàn thành</div><div class="value">${scoped.filter(b=>b.status==='completed').length}</div></div><div class="card"><div class="label">Doanh thu</div><div class="value">${fmtVND(rev)}</div></div><div class="card"><div class="label">Quỹ phòng</div><div class="value">${shown.reduce((s,p)=>s+p.total_rooms,0)}</div></div></div><div class="grid2"><div class="chart"><h3>Doanh thu theo cơ sở</h3><canvas id="property-rev"></canvas></div><div class="chart"><h3>Phân bố trạng thái (theo cơ sở)</h3><canvas id="property-status"></canvas></div></div>`;const rmap={};for(const p of shown)rmap[p.property_name]=scoped.filter(b=>b.property_id===p.property_id&&['confirmed','completed'].includes(b.status)).reduce((s,b)=>s+b.revenue,0)/1e6;mkChart('property-rev','propRev','bar',Object.keys(rmap),Object.values(rmap),'Doanh thu (triệu)',{indexAxis:'y'});mkChart('property-status','propStatus','doughnut',['Đã xác nhận','Hoàn thành','Chờ xử lý','Đã hủy'],['confirmed','completed','pending','cancelled'].map(s=>scoped.filter(b=>b.status===s).length))}
function openPropertyModal(p=null){const rooms=p?.room_types||[{room_type_id:'STD',room_type_name:'Tiêu chuẩn',quantity:1,max_guests_per_room:3,active:true}];document.getElementById('dynamic-modal').innerHTML=`<div class="modal-card wide"><div class="modal-head"><h2>${p?'Sửa':'Thêm'} cơ sở lưu trú</h2><span class="x" onclick="closeModal('dynamic-modal')">&times;</span></div><div class="form-row"><div class="form-group"><label>Mã cơ sở</label><input id="p-id" value="${esc(p?.property_id||'')}" ${p?'disabled':''}></div><div class="form-group"><label>Tên cơ sở</label><input id="p-name" value="${esc(p?.property_name||'')}"></div></div><div class="form-row"><div class="form-group"><label>Mô tả</label><input id="p-profile" value="${esc(p?.profile||'')}"></div><div class="form-group"><label>Đang hoạt động</label><select id="p-active"><option value="true" ${p?.active!==false?'selected':''}>Có</option><option value="false" ${p?.active===false?'selected':''}>Không</option></select></div></div><h3>🛏 Loại phòng & Quỹ phòng</h3><div class="scroll"><table id="room-editor"><thead><tr><th>Mã</th><th>Tên</th><th>Số lượng</th><th>Khách tối đa</th><th>Hoạt động</th><th></th></tr></thead><tbody>${rooms.map(r=>roomRow(r)).join('')}</tbody></table></div><div class="toolbar"><button onclick="addRoomRow()">➕ Thêm loại phòng</button></div><button class="success" onclick="saveProperty('${p?.property_id||''}')">💾 Lưu cơ sở</button></div>`;document.getElementById('dynamic-modal').style.display='block'}
function roomRow(r={}){return `<tr data-original="${esc(r.room_type_id||'')}"><td><input class="rt-id" value="${esc(r.room_type_id||'')}"></td><td><input class="rt-name" value="${esc(r.room_type_name||'')}"></td><td><input class="rt-qty" type="number" min="0" value="${r.quantity??0}"></td><td><input class="rt-cap" type="number" min="1" value="${r.max_guests_per_room??2}"></td><td><select class="rt-active"><option value="true" ${r.active!==false?'selected':''}>Có</option><option value="false" ${r.active===false?'selected':''}>Không</option></select></td><td><button class="danger small" onclick="this.closest('tr').remove()">Bỏ</button></td></tr>`}
function addRoomRow(){document.querySelector('#room-editor tbody').insertAdjacentHTML('beforeend',roomRow())}
async function saveProperty(existing=''){const pid=existing||document.getElementById('p-id').value.trim().toUpperCase(),body={property_id:pid,property_name:document.getElementById('p-name').value.trim(),active:document.getElementById('p-active').value==='true',profile:document.getElementById('p-profile').value.trim()};const rows=[...document.querySelectorAll('#room-editor tbody tr')].map(tr=>({original:tr.dataset.original,room_type_id:tr.querySelector('.rt-id').value.trim().toUpperCase(),room_type_name:tr.querySelector('.rt-name').value.trim(),quantity:+tr.querySelector('.rt-qty').value,max_guests_per_room:+tr.querySelector('.rt-cap').value,active:tr.querySelector('.rt-active').value==='true'})).filter(r=>r.room_type_id&&r.room_type_name);try{if(existing)await api(`/api/properties/${existing}`,{method:'PUT',body});else await api('/api/properties',{method:'POST',body});const old=properties.find(p=>p.property_id===pid)?.room_types||[];for(const r of rows){const ex=old.find(x=>x.room_type_id===r.original);if(ex)await api(`/api/properties/${pid}/room-types/${encodeURIComponent(r.original)}`,{method:'PUT',body:r});else await api(`/api/properties/${pid}/room-types`,{method:'POST',body:r})}for(const oldr of old){if(!rows.some(r=>r.original===oldr.room_type_id)){try{await api(`/api/properties/${pid}/room-types/${encodeURIComponent(oldr.room_type_id)}`,{method:'DELETE'})}catch(e){alert(`Loại phòng ${oldr.room_type_id} chưa được xóa: ${e.message}`)}}}closeModal('dynamic-modal');await loadMasters();loadProperties()}catch(e){alert(e.message)}}
async function deleteProperty(id){if(!confirm(`Xóa ${id}? Nếu có dữ liệu lịch sử tham chiếu, hệ thống sẽ chặn thao tác xóa; khi cần hãy chuyển sang Ngừng hoạt động.`))return;try{await api(`/api/properties/${id}`,{method:'DELETE'});await loadMasters();loadProperties()}catch(e){alert(e.message)}}

function loadImport(){document.getElementById('import').innerHTML=`<h2>📥 Nhập Excel & Lưu vào ứng dụng</h2><div class="notice"><strong>Nhập trực tiếp vào cơ sở dữ liệu:</strong> khi chọn tệp Excel, trình duyệt sẽ hiển thị bản xem trước. Nhấn <strong>Nhập & Lưu vào ứng dụng</strong> để tải tệp trực tiếp lên FastAPI và lưu vĩnh viễn các bản ghi vào SQLite/PostgreSQL. Không cần chạy lệnh PowerShell.</div><div class="notice"><strong>Đồng bộ dữ liệu gốc:</strong> Staff, Properties, Room_Types, Channels và KPI_Targets là dữ liệu gốc. Nên chọn <strong>Thay thế dữ liệu gốc</strong> khi cần nạp lại sạch cho pilot. Khi áp dụng được, dữ liệu lịch sử được giữ lại bằng cách ngừng kích hoạt thay vì xóa không an toàn.</div><div class="toolbar"><input id="excel-file" type="file" accept=".xlsx,.xls" onchange="handleExcelSelected(this.files[0])"><select id="import-mode"><option value="replace" selected>Thay thế dữ liệu gốc</option><option value="merge">Gộp (Merge)</option></select><button id="import-save-btn" class="success" onclick="importExcel()" disabled>📥 Nhập & Lưu vào ứng dụng</button></div><div id="import-file-status" class="notice">Chưa chọn tệp Excel.</div><div id="import-msg"></div><h3>Xem trước dữ liệu nhập — Đặt phòng</h3><div class="scroll"><table><thead><tr><th>Mã đặt phòng</th><th>Nhân viên</th><th>Cơ sở</th><th>Loại phòng</th><th>Kênh</th><th>Ngày đặt</th><th>Nhận phòng</th><th>Số khách</th><th>Doanh thu</th></tr></thead><tbody id="import-preview"><tr><td colspan="8">Chọn tệp Excel để xem trước.</td></tr></tbody></table></div>`}
async function handleExcelSelected(f){const b=document.getElementById('import-save-btn');if(b)b.disabled=!f;if(!f){msg('import-file-status','Chưa chọn tệp Excel.');return}msg('import-file-status',`Đã chọn: <strong>${esc(f.name)}</strong> (${Math.max(1,Math.round(f.size/1024))} KB). Sẵn sàng nhập và lưu vào cơ sở dữ liệu backend.`,'successbox');try{await previewExcel(f)}catch(e){msg('import-msg',`Không xem trước được: ${esc(e.message)}. Bạn vẫn có thể thử Nhập & Lưu vào ứng dụng.`,'error')}}
async function previewExcel(f){if(!f)return;if(typeof XLSX==='undefined'){throw new Error('Thư viện xem trước Excel chưa tải xong')}const buf=await f.arrayBuffer(),wb=XLSX.read(buf,{type:'array'}),ws=wb.Sheets['Bookings']||wb.Sheets[wb.SheetNames[0]],rows=XLSX.utils.sheet_to_json(ws,{defval:''}).slice(0,20);document.getElementById('import-preview').innerHTML=rows.map(r=>`<tr><td>${esc(r.bookingId||r['No.']||'')}</td><td>${esc(r.staffId||'')}</td><td>${esc(r.propertyId||'')}</td><td>${esc(r.roomTypeId||'')}</td><td>${esc(r.channel||'')}</td><td>${esc(r.checkInDate||'')}</td><td>${esc(r.numberOfGuests||'')}</td><td>${esc(r.revenue||'')}</td></tr>`).join('')||'<tr><td colspan="8">Không có dòng xem trước.</td></tr>'}
async function uploadExcelToBackend(f,mode){const fd=new FormData();fd.append('file',f,f.name);const headers={};if(token)headers.Authorization=`Bearer ${token}`;const r=await fetch(`${API}/api/admin/import-excel?mode=${encodeURIComponent(mode)}`,{method:'POST',headers,body:fd});if(r.status===401){logout();throw new Error('Phiên đăng nhập đã hết hạn')}let payload=null;try{payload=await r.clone().json()}catch{}if(!r.ok)throw new Error(payload?.detail||`Nhập thất bại: HTTP ${r.status}`);return payload||{}}
function importCountTable(counts={}){const order=['Staff','Properties','Room_Types','Channels','KPI_Targets','Bookings','Thanh_toan','Lead_CRM'];return `<table><thead><tr><th>Thực thể / Sheet</th><th>Số dòng đã lưu</th></tr></thead><tbody>${order.map(k=>`<tr><td>${k}</td><td><strong>${Number(counts[k]||0)}</strong></td></tr>`).join('')}</tbody></table>`}
async function importExcel(){const input=document.getElementById('excel-file'),f=input?.files?.[0];if(!f)return alert('Hãy chọn tệp .xlsx hoặc .xls trước.');const mode=document.getElementById('import-mode').value,btn=document.getElementById('import-save-btn');if(btn){btn.disabled=true;btn.textContent='⏳ Đang nhập & lưu...'}msg('import-msg',`Đang tải lên <strong>${esc(f.name)}</strong> và lưu vào cơ sở dữ liệu tập trung. Vui lòng chờ...`);try{const j=await uploadExcelToBackend(f,mode);let sync=null;try{sync=await api('/api/data-model/sync-master-dependencies',{method:'POST'})}catch(e){console.warn('Post-import master sync warning:',e)}await loadMasters();const [ready,dash]=await Promise.all([api('/api/validation/readiness'),api('/api/dashboard')]);const persisted=ready.counts||j.persisted_counts||j.counts||{};const imported=j.counts||{};const critical=['Staff','Properties','Room_Types','Channels','KPI_Targets','Bookings'];const emptyCritical=critical.filter(k=>Number(persisted[k]||0)===0&&Number(imported[k]||0)>0);if(emptyCritical.length)throw new Error(`Đã nhận dữ liệu nhưng chưa lưu được cho: ${emptyCritical.join(', ')}`);await loadDashboard();const warnings=(j.warnings||[]).length?`<br><strong>Cảnh báo:</strong><br>${j.warnings.map(esc).join('<br>')}`:'<br><strong>Cảnh báo:</strong> Không có';const syncInfo=sync?`<br><strong>Đồng bộ phụ thuộc dữ liệu gốc:</strong> hoàn tất; số chỉ tiêu KPI không còn liên kết đã xóa: ${sync.removed_kpi_targets||0}.`:'';msg('import-msg',`<strong>✅ Đã nhập Excel và lưu vào cơ sở dữ liệu thành công.</strong><br>Tệp: ${esc(f.name)}<br>Chế độ: ${esc(mode==='replace'?'Thay thế dữ liệu gốc':'Gộp (Merge)')}<br>Số đặt phòng hiện có trên Tổng quan: <strong>${Number(dash.bookings||0)}</strong>.${syncInfo}${warnings}<div class="scroll" style="margin-top:10px">${importCountTable(persisted)}</div><div class="toolbar" style="margin-top:10px"><button onclick="showView('dashboard')">📈 Mở Tổng quan</button><button onclick="showView('datamodel')">🧩 Mở Mô hình dữ liệu</button><button onclick="showView('validation')">✅ Chạy kiểm tra dữ liệu</button></div>`,'successbox')}catch(e){msg('import-msg',`<strong>❌ Dữ liệu nhập chưa được lưu.</strong><br>${esc(e.message)}<br>Hãy giữ backend đang chạy và thử lại. Không cần chạy lệnh nhập bằng PowerShell.`,'error')}finally{if(btn){btn.disabled=false;btn.textContent='📥 Nhập & Lưu vào ứng dụng'}}}

function loadExport(){document.getElementById('export').innerHTML=`<h2>📤 Lưu & Xuất dữ liệu</h2><div class="notice">V1.0.2 đọc/ghi trực tiếp cơ sở dữ liệu tập trung, không dùng localStorage của trình duyệt cho dữ liệu nghiệp vụ. Vì vậy “Lưu toàn bộ dữ liệu” chỉ là điểm xác nhận tính nhất quán của cơ sở dữ liệu.</div><div class="export-grid"><button class="success" onclick="saveAllCheckpoint()">💾 Lưu toàn bộ dữ liệu</button><button class="success" onclick="exportExcel()">📗 Xuất toàn bộ tệp Excel</button><button class="success" onclick="download('/api/export/bookings-csv','bookings_v1.0.2.csv')">📥 Đặt phòng CSV</button><button class="success" onclick="download('/api/export/staff-csv','staff_v1.0.2.csv')">📥 Nhân viên CSV</button><button onclick="download('/api/export/all-json','all_data_v1.0.2.json')">📥 Toàn bộ dữ liệu JSON</button>${me.role==='admin'?'<button class="danger" onclick="resetData()">🔄 Xóa dữ liệu (Reset)</button>':''}</div><div id="export-status" class="notice"><strong>Trạng thái lưu:</strong> Backend ghi dữ liệu vào cơ sở dữ liệu ngay lập tức.</div><div class="notice"><strong>Bảo mật:</strong> mã băm mật khẩu không bao giờ được xuất.</div>`}
function saveAllCheckpoint(){msg('export-status','<strong>Trạng thái lưu:</strong> ✅ Mọi thao tác thêm/sửa/xóa đã được ghi vào cơ sở dữ liệu. Có thể xuất dữ liệu.','successbox')}
async function exportExcel(){try{await download('/api/export/workbook','Non_Ecolodge_Sales_KPI_V1.0.2.xlsx')}catch(e){alert(e.message)}}
async function resetData(){if(!confirm('Thao tác này xóa dữ liệu nghiệp vụ pilot (Nhân viên/Cơ sở/Đặt phòng/KPI...) nhưng giữ tài khoản người dùng. Tiếp tục?'))return;const x=prompt('Gõ RESET để xác nhận');if(x!=='RESET')return;try{const r=await api('/api/admin/reset-data?confirm=RESET',{method:'POST'});alert(r.message);await loadMasters();showView('dashboard')}catch(e){alert(e.message)}}

async function loadAudit(){const rows=await api('/api/audit');document.getElementById('auditlog').innerHTML=`<h2>📋 Nhật ký thao tác</h2><div class="toolbar"><button class="success" onclick="download('/api/audit/export-csv','audit_log_v1.0.2.csv')">📥 Xuất nhật ký (CSV)</button></div><div class="notice">Bản ghi nhật ký không thể thay đổi trong V1.0.2: có thể lọc/xuất, nhưng không sửa hoặc xóa trên giao diện.</div><div class="scroll"><table><thead><tr><th>Thời điểm</th><th>Người dùng</th><th>Thao tác</th><th>Thực thể</th><th>Mã</th><th>Chi tiết</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${a.timestamp}</td><td>${a.username}</td><td>${a.action}</td><td>${a.entity}</td><td>${a.entity_id}</td><td>${esc(a.details)}</td></tr>`).join('')}</tbody></table></div>`}
async function loadAuditPanel(){const [s,rows,users]=await Promise.all([api('/api/audit/summary'),api('/api/audit/filter'),api('/api/users')]);const actions=[...new Set(rows.map(x=>x.action))].sort();document.getElementById('auditpanel').innerHTML=`<h2>🔍 Phân tích & Giám sát nhật ký</h2><div class="cards"><div class="card"><div class="label">Tổng thao tác</div><div class="value">${s.total_actions}</div></div><div class="card"><div class="label">Số người dùng</div><div class="value">${s.unique_users}</div></div><div class="card"><div class="label">Loại thao tác</div><div class="value">${s.action_types}</div></div><div class="card"><div class="label">Thao tác hôm nay</div><div class="value">${s.today_actions}</div></div></div><div class="filter-box"><h3>🔎 Bộ lọc & Tìm kiếm</h3><div class="form-row"><div class="form-group"><label>Người dùng</label><select id="af-user"><option value="">Tất cả người dùng</option>${[...new Set(rows.map(x=>x.username))].sort().map(x=>`<option>${x}</option>`).join('')}</select></div><div class="form-group"><label>Loại thao tác</label><select id="af-action"><option value="">Tất cả thao tác</option>${actions.map(x=>`<option>${x}</option>`).join('')}</select></div></div><div class="form-group"><label>Khoảng thời gian</label><select id="af-days"><option value="">Mọi thời gian</option><option value="1">Hôm nay / 24 giờ</option><option value="7">7 ngày qua</option><option value="30">30 ngày qua</option></select></div><div class="toolbar"><button onclick="applyAuditFilters()">🔍 Áp dụng bộ lọc</button><button class="secondary" onclick="loadAuditPanel()">↺ Đặt lại</button><button class="success" onclick="exportAuditFiltered()">📥 Xuất CSV</button></div></div><h3>🔐 Quản lý tài khoản người dùng</h3><div class="toolbar"><button class="success" onclick="openUserModal()">➕ Tạo tài khoản & mật khẩu</button></div><div class="scroll"><table><thead><tr><th>Tên đăng nhập</th><th>Họ tên</th><th>Vai trò</th><th>Mã NV</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>${users.map(x=>userRow(x)).join('')}</tbody></table></div><h3>📋 Nhật ký (hoạt động gần đây)</h3><div id="audit-filter-results">${auditTable(rows)}</div><div class="cards">${Object.entries(s.by_action||{}).slice(0,8).map(([k,v])=>`<div class="card"><div class="label">${esc(k)}</div><div class="value">${v}</div></div>`).join('')}</div>`}
function auditTable(rows){return `<div class="scroll"><table><thead><tr><th>Thời điểm</th><th>Người dùng</th><th>Thao tác</th><th>Thực thể</th><th>Mã</th><th>Chi tiết</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${a.timestamp}</td><td>${a.username}</td><td>${a.action}</td><td>${a.entity}</td><td>${a.entity_id}</td><td>${esc(a.details)}</td></tr>`).join('')}</tbody></table></div>`}
async function applyAuditFilters(){const u=document.getElementById('af-user').value,a=document.getElementById('af-action').value,d=document.getElementById('af-days').value;const q=new URLSearchParams();if(u)q.set('username',u);if(a)q.set('action',a);if(d)q.set('days',d);const rows=await api('/api/audit/filter?'+q);document.getElementById('audit-filter-results').innerHTML=auditTable(rows)}
function exportAuditFiltered(){const q=new URLSearchParams(),u=document.getElementById('af-user').value,a=document.getElementById('af-action').value,d=document.getElementById('af-days').value;if(u)q.set('username',u);if(a)q.set('action',a);if(d)q.set('days',d);download('/api/audit/export-csv?'+q,'audit_filtered_v1.0.2.csv').catch(e=>alert(e.message))}

async function loadValidation(){const [d,cfg,ready]=await Promise.all([api('/api/validation'),api('/api/settings/kpi-sla'),api('/api/validation/readiness')]);const chans=channels.length?channels:await api('/api/channels');document.getElementById('validation').innerHTML=`<h2>✅ Trung tâm kiểm tra dữ liệu & chức năng</h2><div class="notice">Dùng tab này trước mỗi phiên pilot. Sửa lỗi an toàn không thay đổi trạng thái đặt phòng, cơ sở, doanh thu, kênh bán hoặc phân khúc khách hàng.</div><div class="cards"><div class="card"><div class="label">Kết quả nghiệm thu</div><div class="value">${d.summary.gate==='PASS'?'ĐẠT':d.summary.gate==='FAIL'?'KHÔNG ĐẠT':esc(d.summary.gate)}</div></div><div class="card"><div class="label">Lỗi</div><div class="value">${d.summary.errors}</div></div><div class="card"><div class="label">Cảnh báo</div><div class="value">${d.summary.warnings}</div></div><div class="card"><div class="label">Số đặt phòng</div><div class="value">${d.summary.bookings}</div></div></div><div class="toolbar"><button class="success" onclick="loadValidation()">▶ Chạy kiểm tra</button><button class="warn" onclick="repairValidation()">🛠 Sửa lỗi an toàn</button><button onclick="download('/api/validation/export-csv','validation_v1.0.2.csv')">📥 Xuất kết quả kiểm tra CSV</button></div><div class="notice ${d.summary.errors?'error':'successbox'}">${d.summary.errors?'Chưa đạt điều kiện nghiệm thu pilot. Xem các lỗi chặn bên dưới.':'Đạt điều kiện nghiệm thu pilot: không có lỗi chặn.'}</div><div class="grid2"><div class="chart"><h3>Quy tắc kiểm tra</h3><table><tbody><tr><td>Mã đặt phòng</td><td>Bắt buộc và không trùng lặp</td></tr><tr><td>Liên kết nhân viên</td><td>staff_id phải tồn tại</td></tr><tr><td>Cơ sở</td><td>property_id phải tồn tại</td></tr><tr><td>Loại phòng</td><td>Cơ sở + Loại phòng phải tồn tại và sức chứa phải đủ cho số khách</td></tr><tr><td>Ngày</td><td>Ngày trả phòng phải sau ngày nhận phòng</td></tr><tr><td>Trạng thái</td><td>Đã xác nhận / Hoàn thành / Chờ xử lý / Đã hủy</td></tr><tr><td>Kênh bán</td><td>Kênh đã được phê duyệt</td></tr><tr><td>Phân khúc</td><td>Nghỉ dưỡng / Công tác / Đoàn</td></tr><tr><td>Chỉ tiêu KPI</td><td>Chỉ tiêu doanh thu và đêm phòng phải lớn hơn 0</td></tr></tbody></table></div><div class="chart"><h3>Điều kiện nghiệm thu pilot</h3><p>${d.summary.gate==='PASS'?'✅ Không có lỗi chặn.':'❌ Đang có lỗi chặn.'}</p><p>Lỗi: ${d.summary.errors}; Cảnh báo: ${d.summary.warnings}</p></div></div><h3>🎯 Chỉ tiêu KPI & Quy tắc SLA</h3><div class="grid2"><div class="chart"><div class="form-group"><label>Chỉ tiêu doanh thu tháng mặc định (VND)</label><input id="cfg-rev" type="number" value="${cfg.revenue_target_vnd}"></div><div class="form-group"><label>Chỉ tiêu đêm phòng tháng mặc định</label><input id="cfg-rn" type="number" value="${cfg.room_night_target}"></div><div class="form-group"><label>Chỉ tiêu tỷ lệ chuyển đổi (%)</label><input id="cfg-conv" type="number" value="${cfg.conversion_target_pct*100}"></div><div class="form-group"><label>Chỉ tiêu thanh toán đúng hạn (%)</label><input id="cfg-pay" type="number" value="${cfg.payment_target_pct*100}"></div><div class="form-group"><label>Chỉ tiêu tuân thủ SLA (%)</label><input id="cfg-sla" type="number" value="${cfg.sla_compliance_target_pct*100}"></div></div><div class="chart"><h3>Quy tắc SLA theo kênh</h3><table><thead><tr><th>Kênh</th><th>SLA phản hồi (phút)</th></tr></thead><tbody>${chans.map(c=>`<tr><td>${esc(c.channel_name)}</td><td><input class="sla-input" data-channel="${esc(c.channel_name)}" type="number" min="1" value="${cfg.sla_minutes[c.channel_name]||c.response_sla_minutes}"></td></tr>`).join('')}</tbody></table></div></div><div class="toolbar"><button class="success" onclick="saveKpiSla()">💾 Lưu chỉ tiêu KPI & SLA</button><button onclick="loadValidation()">↺ Tải lại quy tắc</button><button class="warn" onclick="resetKpiSla()">Khôi phục mặc định</button></div><h3>📚 Mức sẵn sàng dữ liệu (nhiều sheet / cơ sở dữ liệu)</h3><div class="notice">${ready.last_import?`Lần nhập gần nhất: ${esc(ready.last_import.file_name)} lúc ${esc(ready.last_import.imported_at)} (${esc(ready.last_import.mode)})`:'Cơ sở dữ liệu chưa ghi nhận lần nhập tệp Excel nào.'}</div><div class="scroll"><table><thead><tr><th>Thực thể / Sheet</th><th>Số dòng</th><th>Trạng thái</th><th>Mục đích</th></tr></thead><tbody>${Object.entries(ready.counts).map(([k,v])=>`<tr><td>${k}</td><td>${v}</td><td>${v>0?'✅ Sẵn sàng':'⚠️ Trống'}</td><td>Dữ liệu trong cơ sở dữ liệu tập trung</td></tr>`).join('')}</tbody></table></div><h3>Các vấn đề phát hiện</h3><div class="scroll"><table><thead><tr><th>Mức độ</th><th>Thực thể</th><th>Mã</th><th>Trường</th><th>Vấn đề</th><th>Đề xuất xử lý</th></tr></thead><tbody>${d.issues.length?d.issues.map(i=>`<tr><td>${sevVI(i.severity)}</td><td>${i.entity}</td><td>${i.id}</td><td>${i.field}</td><td>${esc(i.issue)}</td><td>${esc(i.suggested_action)}</td></tr>`).join(''):'<tr><td colspan="6">✅ Không có vấn đề.</td></tr>'}</tbody></table></div>`}
async function repairValidation(){if(!confirm('Chỉ áp dụng sửa lỗi an toàn cho dữ liệu dẫn xuất (ví dụ: số phòng theo sức chứa, hoa hồng tính sai)?'))return;try{const r=await api('/api/validation/repair-safe',{method:'POST'});alert(`Số lỗi đã sửa an toàn: ${r.repairs.length}\n${r.repairs.slice(0,20).join('\n')}`);loadValidation()}catch(e){alert(e.message)}}
async function saveKpiSla(){const sla={};document.querySelectorAll('.sla-input').forEach(x=>sla[x.dataset.channel]=+x.value);const body={revenue_target_vnd:+document.getElementById('cfg-rev').value,room_night_target:+document.getElementById('cfg-rn').value,conversion_target_pct:+document.getElementById('cfg-conv').value/100,payment_target_pct:+document.getElementById('cfg-pay').value/100,sla_compliance_target_pct:+document.getElementById('cfg-sla').value/100,sla_minutes:sla};try{await api('/api/settings/kpi-sla',{method:'PUT',body});await loadMasters();alert('Đã lưu chỉ tiêu KPI & quy tắc SLA.');loadValidation()}catch(e){alert(e.message)}}
async function resetKpiSla(){if(!confirm('Khôi phục cấu hình KPI/SLA mặc định?'))return;await api('/api/settings/kpi-sla/reset',{method:'POST'});loadValidation()}

async function loadUsers(){const u=await api('/api/users');document.getElementById('users').innerHTML=`<h2>🔐 Quản lý tài khoản người dùng</h2><div class="toolbar"><button class="success" onclick="openUserModal()">➕ Tạo tài khoản & mật khẩu</button></div><div class="notice">Mật khẩu được băm PBKDF2-SHA256 ở backend và không bao giờ được xuất. Tài khoản nhân viên phải liên kết với một mã nhân viên.</div><div class="scroll"><table><thead><tr><th>Tên đăng nhập</th><th>Họ tên</th><th>Vai trò</th><th>Mã NV</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>${u.map(x=>userRow(x)).join('')}</tbody></table></div>`}
function userRow(x){return `<tr><td>${x.username}</td><td>${esc(x.full_name)}</td><td>${roleVI(x.role)}</td><td>${x.staff_id||'—'}</td><td>${x.active?'✅ Đang hoạt động':'🔒 Đã khóa'}</td><td><button class="warn small" onclick='openUserModal(${JSON.stringify(x)})'>Mật khẩu / Sửa</button><button class="secondary small" onclick='toggleUser(${JSON.stringify(x)})'>${x.active?'Khóa':'Mở khóa'}</button>${x.id===me.id?'':`<button class="danger small" onclick="deleteUser(${x.id})">Xóa</button>`}</td></tr>`}
function openUserModal(u=null){document.getElementById('u-staff').innerHTML='<option value="">-- không liên kết --</option>'+staff.map(s=>`<option value="${s.staff_id}">${s.staff_id} - ${esc(s.staff_name)}</option>`).join('');document.getElementById('u-username').value=u?.username||'';document.getElementById('u-name').value=u?.full_name||'';document.getElementById('u-password').value='';document.getElementById('u-role').value=u?.role||'staff';document.getElementById('u-staff').value=u?.staff_id||'';document.getElementById('user-modal').dataset.id=u?.id||'';document.querySelector('#user-modal h2').textContent=u?'Sửa tài khoản / mật khẩu':'Tạo tài khoản';document.getElementById('user-modal').style.display='block'}
async function saveUser(){const id=document.getElementById('user-modal').dataset.id,body={username:document.getElementById('u-username').value,full_name:document.getElementById('u-name').value,password:document.getElementById('u-password').value||null,role:document.getElementById('u-role').value,staff_id:document.getElementById('u-staff').value||null,active:true};try{if(!id&&!body.password)return alert('Tài khoản mới bắt buộc phải có mật khẩu');await api(id?`/api/users/${id}`:'/api/users',{method:id?'PUT':'POST',body});closeModal('user-modal');await loadUsers()}catch(e){alert(e.message)}}
async function toggleUser(u){const body={username:u.username,full_name:u.full_name,password:null,role:u.role,staff_id:u.staff_id,active:!u.active};try{await api(`/api/users/${u.id}`,{method:'PUT',body});loadUsers()}catch(e){alert(e.message)}}
async function deleteUser(id){if(!confirm('Xóa tài khoản người dùng này?'))return;try{await api(`/api/users/${id}`,{method:'DELETE'});loadUsers()}catch(e){alert(e.message)}}

boot();


// V1.02h — full booking calendar, one-way iCalendar subscription/export.
async function openGoogleCalendarLink(){
  const modal=document.getElementById('dynamic-modal');
  modal.innerHTML=`<div class="modal-card"><div class="modal-head"><h2>🔗 Liên kết Google Calendar</h2><span class="x" onclick="closeModal('dynamic-modal')">&times;</span></div><div id="google-calendar-body">Đang kiểm tra kết nối…</div></div>`;
  modal.style.display='block';
  try{
    const info=await api('/api/booking-calendar/google-link');
    document.getElementById('google-calendar-body').innerHTML=`
      <div class="notice"><strong>Toàn bộ cơ sở · Toàn bộ ngày · Toàn bộ đặt phòng</strong><br>Không phụ thuộc bộ lọc cơ sở hoặc khoảng thời gian đang xem. Gồm mã đặt phòng, cơ sở, loại phòng, mã nhân viên, ngày đến/đi, số phòng và trạng thái.</div>
      <h3>1. Liên kết tự cập nhật</h3>
      <p>Đồng bộ một chiều: ứng dụng → Google Calendar. Google tự làm mới lịch theo chu kỳ; nút Đồng bộ trong ứng dụng không buộc Google cập nhật ngay. Hãy sửa đặt phòng trong ứng dụng.</p>
      ${info.subscription_available?`<div class="notice ${info.has_existing_link?'warning':''}">${info.has_existing_link?'Bạn đã có liên kết đang hoạt động. Không cần tạo lại nếu đã thêm vào Google Calendar. Tạo lại sẽ vô hiệu hóa liên kết cũ; bạn cần thêm liên kết mới vào Google.':'Tạo liên kết, sao chép rồi mở Google Calendar để thêm lịch.'}</div>`:'<div class="notice warning">Backend chưa có PUBLIC_BASE_URL HTTPS công khai. Google không đọc được địa chỉ localhost hoặc 127.0.0.1. Hiện tại hãy dùng Download .ics bên dưới. Hướng dẫn cấu hình nằm trong docs/GOOGLE_CALENDAR_VI.md.</div>'}
      <div class="toolbar"><button id="google-create-link" ${info.subscription_available?'':'disabled'} onclick="createGoogleCalendarLink(${info.has_existing_link})">${info.has_existing_link?'Tạo lại liên kết':'Tạo liên kết'}</button><button class="danger" id="google-revoke-link" ${info.has_existing_link?'':'disabled'} onclick="revokeGoogleCalendarLink()">Thu hồi liên kết</button></div>
      <div id="google-link-result"></div><div id="google-link-message"></div>
      <p>Liên kết chứa khóa riêng: người có liên kết xem được thông tin lịch. Thu hồi ngừng các lần tải tiếp theo, không xóa bản sao Google đã lưu.</p>
      <h3>2. Dùng ngay khi chạy trên máy cá nhân</h3>
      <div class="toolbar"><button class="success" onclick="downloadGoogleCalendar(this)">📥 Tải tệp .ics — Toàn bộ đặt phòng</button><a href="https://calendar.google.com/calendar/u/0/r/settings/export" target="_blank" rel="noopener noreferrer">Mở Google Calendar để nhập</a></div>
      <p>Trong Google Calendar: Settings → Import &amp; export → chọn tệp .ics → chọn lịch đích → Import. Nên tạo lịch riêng “Non Ecolodge Bookings”. Đây là bản chụp dữ liệu tại lúc tải, không tự cập nhật khi nhập bằng tệp.</p>
      <p class="muted">Mỗi đặt phòng là một sự kiện cả ngày, kết thúc trước ngày trả phòng. Tên sự kiện có mã cơ sở; Google có thể dùng một màu chung cho lịch, không giữ bảng màu của ứng dụng. Đặt phòng Đã hủy được đánh dấu hủy và có thể bị Google ẩn. Dữ liệu doanh thu, thanh toán, ghi chú nội bộ không đưa vào lịch.</p>`;
  }catch(e){document.getElementById('google-calendar-body').innerHTML=`<div class="notice error">${esc(e.message)}</div>`}
}
async function createGoogleCalendarLink(replaceExisting){
  if(replaceExisting&&!confirm('Tạo lại sẽ vô hiệu hóa liên kết cũ. Bạn sẽ cần thêm URL mới vào Google Calendar. Tiếp tục?'))return;
  const button=document.getElementById('google-create-link');button.disabled=true;
  try{
    const result=await api('/api/booking-calendar/google-link',{method:'POST'});
    document.getElementById('google-link-result').innerHTML=`<label><strong>URL lịch (chỉ hiện khi tạo):</strong></label><input id="google-calendar-url" readonly value="${esc(result.url)}" onclick="this.select()"><div class="toolbar"><button onclick="copyGoogleCalendarLink()">Sao chép URL</button><a href="https://calendar.google.com/calendar/u/0/r/settings/addbyurl" target="_blank" rel="noopener noreferrer">Mở Google Calendar — From URL</a></div><p>Dán URL ở trên vào ô URL of calendar rồi chọn Add calendar. Giữ kín liên kết này. Đừng chọn công khai lịch.</p>`;
    document.getElementById('google-revoke-link').disabled=false;
    button.textContent='Tạo lại liên kết';button.onclick=()=>createGoogleCalendarLink(true);
    msg('google-link-message','Đã tạo liên kết. Bạn cần thêm URL vào Google Calendar để hoàn tất.','successbox');
  }catch(e){msg('google-link-message',esc(e.message),'error')}finally{button.disabled=false}
}
async function copyGoogleCalendarLink(){
  const field=document.getElementById('google-calendar-url');
  try{await navigator.clipboard.writeText(field.value);msg('google-link-message','Đã sao chép URL. Mở Google Calendar và dán vào From URL.','successbox')}
  catch{field.focus();field.select();msg('google-link-message','URL đã được chọn. Nhấn Ctrl+C để sao chép.','warning')}
}
async function revokeGoogleCalendarLink(){
  if(!confirm('Thu hồi liên kết lịch của tài khoản này? Google sẽ không tải được các cập nhật tiếp theo.'))return;
  try{await api('/api/booking-calendar/google-link',{method:'DELETE'});await openGoogleCalendarLink();msg('google-link-message','Đã thu hồi liên kết. Bạn có thể xóa lịch đã thêm trong Google Calendar.','successbox')}
  catch(e){msg('google-link-message',esc(e.message),'error')}
}
async function downloadGoogleCalendar(button){
  button.disabled=true;
  try{await download('/api/booking-calendar/export.ics','Non_Ecolodge_All_Bookings.ics');msg('google-link-message','Đã tải tệp .ics. Mở Google Calendar → Settings → Import & export để nhập.','successbox')}
  catch(e){msg('google-link-message',esc(e.message),'error')}finally{button.disabled=false}
}
